// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  Img,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: interFamily } = loadInter();



export type PeleYearRevealProps = Record<string, any>;

const PeleYearReveal: React.FC<PeleYearRevealProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 12,
  years = [
    {
      year: "1958",
      title: "PELE EMERGES",
      subtitle:
        "A 17-year-old prodigy stuns the world in Sweden, scoring twice in the final to secure Brazil's first World Cup title.",
    },
    {
      year: "1962",
      title: "BACK TO BACK Glory",
      subtitle:
        "Despite an early injury, Pelé's magnetic presence inspires Brazil to retain their crown as undisputed champions of the world.",
    },
    {
      year: "1970",
      title: "THE ULTIMATE TRIUMPH",
      subtitle:
        "The peak of Jogo Bonito. Pelé orchestrates one of the greatest football teams ever assembled to claim a historic third title.",
    },
  ],
  imageSrc = "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/images/pelebrazil.webp",
  grayscale = true,
  contrast = 1.1,
  fontSize = 450,
  titleFontSize = 28,
  subtitleFontSize = 17,
  spacingFactor = 0.62,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse safety for background transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Detect contrast color for typography
  const isBackgroundDark = (hexColor: string) => {
    const color = hexColor.replace("#", "");
    if (color.length !== 6) return false;
    const r = parseInt(color.substring(0, 2), 16);
    const g = parseInt(color.substring(2, 4), 16);
    const b = parseInt(color.substring(4, 6), 16);
    const brightness = (r * 299 + g * 587 + b * 114) / 1000;
    return brightness < 128;
  };

  const isDark = isBackgroundDark(backgroundColor);
  const textColor = isDark ? "#ffffff" : "#111111";
  const subtitleColor = isDark
    ? "rgba(255, 255, 255, 0.7)"
    : "rgba(0, 0, 0, 0.65)";

  const totalFrames = durationInSeconds * fps;
  const segmentFrames = totalFrames / years.length;

  // Custom filter style for image
  const filterStyle = `${
    grayscale ? "grayscale(100%)" : ""
  } contrast(${contrast})`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Hidden image preloader to ensure asset loaded warning fix */}
      <Img
        src={imageSrc}
        style={{
          opacity: 0,
          position: "absolute",
          left: "-9999px",
          width: "10px",
          height: "10px",
        }}
      />

      {/* Render years sequentially */}
      {years.map((yearItem, index) => {
        const startFrame = index * segmentFrames;
        const endFrame = (index + 1) * segmentFrames;

        // Transition bounds
        const transitionFrames = Math.min(15, segmentFrames * 0.15);

        // Compute year segment overall opacity
        let yearOpacity = 0;
        if (frame >= startFrame && frame <= endFrame) {
          const fadeIn = interpolate(
            frame,
            [startFrame, startFrame + transitionFrames],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const fadeOut = interpolate(
            frame,
            [endFrame - transitionFrames, endFrame],
            [1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          if (index === 0) {
            yearOpacity = fadeOut;
          } else if (index === years.length - 1) {
            yearOpacity = fadeIn;
          } else {
            yearOpacity = Math.min(fadeIn, fadeOut);
          }
        }

        // Skip rendering if not visible to maintain optimal performance
        if (yearOpacity <= 0) {
          return null;
        }

        const localFrame = frame - startFrame;

        // Slow parallax image zoom & slide
        const imageScale = interpolate(
          localFrame,
          [0, segmentFrames],
          [1.05, 1.25],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const imageTranslateX = interpolate(
          localFrame,
          [0, segmentFrames],
          [-20, 20],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const imageTranslateY = interpolate(
          localFrame,
          [0, segmentFrames],
          [-10, 10],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Caption elements animation
        const captionStartFrame = 15;
        const captionProgress = interpolate(
          localFrame,
          [captionStartFrame, captionStartFrame + 15],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const captionY = interpolate(
          localFrame,
          [captionStartFrame, captionStartFrame + 15],
          [20, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Digits breakdown
        const yearDigits = yearItem.year.split("");
        const centerY = height * 0.42;
        const charSpacing = fontSize * spacingFactor;

        return (
          <AbsoluteFill
            key={index}
            style={{
              opacity: yearOpacity,
              zIndex: index,
              transition: "none",
            }}
          >
            {/* SVG Masking Area */}
            <svg
              width="100%"
              height="100%"
              viewBox={`0 0 ${width} ${height}`}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                height: "100%",
              }}
            >
              <defs>
                <clipPath id={`clip-${index}`}>
                  {yearDigits.map((char, charIdx) => {
                    const charX =
                      width / 2 + (charIdx - (yearDigits.length - 1) / 2) * charSpacing;

                    // Staggered springs for individual digit pops
                    const digitFrame = localFrame - charIdx * 4;
                    const digitSpring = spring({
                      fps,
                      frame: Math.max(0, digitFrame),
                      config: {
                        damping: 14,
                        mass: 0.6,
                        stiffness: 90,
                      },
                    });

                    // Ensure scale is exactly 0 before animation begins
                    const digitScale = digitFrame < 0 ? 0 : digitSpring;

                    // Small bounce offset
                    const digitYOffset = interpolate(
                      digitScale,
                      [0, 1],
                      [40, 0]
                    );

                    return (
                      <text
                        key={charIdx}
                        x={charX}
                        y={centerY + digitYOffset}
                        textAnchor="middle"
                        dominantBaseline="central"
                        fontSize={fontSize * digitScale}
                        style={{
                          fontFamily: montserratFamily,
                          fontWeight: 900,
                          transition: "none",
                        }}
                      >
                        {char}
                      </text>
                    );
                  })}
                </clipPath>
              </defs>

              {/* Outside Canvas background mask */}
              <rect width="100%" height="100%" fill={bgColor} />

              {/* The image is only rendered/visible through the text clip path */}
              <image
                href={imageSrc}
                width={width}
                height={height}
                preserveAspectRatio="xMidYMid slice"
                clipPath={`url(#clip-${index})`}
                style={{
                  filter: filterStyle,
                }}
                transform={`translate(${width / 2}, ${height / 2}) scale(${imageScale}) translate(${-width / 2 + imageTranslateX}, ${-height / 2 + imageTranslateY})`}
              />
            </svg>

            {/* Typography & Subtitles */}
            <div
              style={{
                position: "absolute",
                top: height * 0.72,
                left: "10%",
                width: "80%",
                textAlign: "center",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                zIndex: 5,
              }}
            >
              <div
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 800,
                  fontSize: titleFontSize * (width / 1920),
                  color: textColor,
                  textTransform: "uppercase",
                  letterSpacing: "6px",
                  opacity: captionProgress,
                  transform: `translateY(${captionY}px)`,
                  transition: "none",
                  marginBottom: 10,
                }}
              >
                {yearItem.title}
              </div>
              <div
                style={{
                  fontFamily: interFamily,
                  fontWeight: 400,
                  fontSize: subtitleFontSize * (width / 1920),
                  color: subtitleColor,
                  maxWidth: Math.min(width * 0.5, 680),
                  lineHeight: 1.6,
                  opacity: captionProgress,
                  transform: `translateY(${captionY}px)`,
                  transition: "none",
                }}
              >
                {yearItem.subtitle}
              </div>
            </div>
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

export default PeleYearReveal;